import type { CaseStudy, Item } from '../types';

const base = { ngn: true, qa: 'reviewed' as const };
const R = (n: number[]) => n.map(t => `Instructor HESI Review #${t}`);
type Seg = { text: string; key: boolean | null };
/** build highlight segments from [text, key] pairs, inserting spaces */
const segs = (lead: string, parts: [string, boolean][]): Seg[] => {
  const out: Seg[] = [{ text: lead, key: null }];
  parts.forEach(([t, k], i) => { if (i) out.push({ text: ' ', key: null }); out.push({ text: t, key: k }); });
  return out;
};
const mk = (caseId: string, stage: number, it: Record<string, unknown>): Item => ({ ...base, caseId, stage, id: `${caseId}-${stage}`, ...it } as unknown as Item);

